import React from 'react';

export default function EquipmentCard({ equipment, onBorrow }) {
  const isAvailable = equipment.availableStock > 0;

  return (
    <div style={{
      background: '#FFFFFF',
      borderRadius: '12px',
      overflow: 'hidden',
      border: '1px solid #E2E8F0',
      boxShadow: '0 2px 8px rgba(0,0,0,0.04)',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'space-between'
    }}>
      <div>
        <img 
          src={equipment.image} 
          alt={equipment.name}
          style={{ width: '100%', height: '180px', objectFit: 'cover' }}
        />
        <div style={{ padding: '16px' }}>
          <span style={{
            fontSize: '12px',
            color: '#2563EB',
            background: '#EFF6FF',
            padding: '4px 8px',
            borderRadius: '4px',
            fontWeight: '600'
          }}>
            {equipment.category}
          </span>
          <h3 style={{ fontSize: '16px', margin: '10px 0 6px 0', color: '#1E293B' }}>{equipment.name}</h3>
          <p style={{ fontSize: '13px', color: '#64748B', margin: 0, lineHeight: '1.4' }}>
            {equipment.description}
          </p>
        </div>
      </div>

      <div style={{ padding: '16px', paddingTop: 0, borderTop: 'none' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <span style={{ fontSize: '13px', color: '#64748B' }}>คงเหลือ:</span>
          <span style={{ 
            fontSize: '13px', 
            fontWeight: 'bold', 
            color: isAvailable ? '#16A34A' : '#DC2626' 
          }}>
            {equipment.availableStock} / {equipment.totalStock} ชิ้น
          </span>
        </div>

        <button
          onClick={() => onBorrow(equipment)}
          disabled={!isAvailable}
          style={{
            width: '100%',
            padding: '10px',
            background: isAvailable ? '#2563EB' : '#94A3B8',
            color: '#FFFFFF',
            border: 'none',
            borderRadius: '8px',
            fontWeight: '600',
            cursor: isAvailable ? 'pointer' : 'not-allowed',
            fontSize: '14px'
          }}
        >
          {isAvailable ? 'ยืมอุปกรณ์' : 'ของหมด'}
        </button>
      </div>
    </div>
  );
}
